    GuideTopic("request-patterns", "계산기의 평소 사용 설정", "주간 일주일 일수 기본 나머지 구성 직접 입력 추가 사용 변경일", listOf(
        GuideStep("일주일의 사용 구성을 골라요", "평소 사용 바꾸기에서 사용 구성을 고르고 기본 구성을 선택하세요. 처음에는 매일 기본 구성을 사용하는 것으로 계산해요. + 다른 구성도 사용해요로 구성을 추가하고 − / +로 주당 일수를 정해요. 기본 구성은 남은 일수를 자동으로 맡아요.", "51-request-patterns"),
        GuideStep("추가 사용과 직접 입력도 가능해요", "같은 날 더 사용하는 물품 조합이 있으면 + 추가로 사용하는 구성에서 주당 횟수를 정해요. 저장된 구성이 없다면 품목별 직접 입력을 선택하고 하루 또는 일주일 사용량을 적어요. 품목·수량 수정은 이번 계산에만 적용되고 원래 구성은 유지돼요."),
        GuideStep("사용이 바뀌는 날짜를 지정해요", "이 사용으로 계산을 누르면 계산기로 돌아와요. 참고 기간 · 사용 변경을 펼쳐 + 방문일부터 사용이 달라져요 또는 + 중간에 사용이 바뀌어요를 선택하세요. 구성 적용 후 사용 변경일을 확인해요. 변경일은 서로 겹치지 않게 정하며 변경 삭제로 해제할 수 있어요."),
        GuideStep("주간 일수는 비율로 계산해요", "일주일에 A 2일, B 3일, 기본 구성 2일처럼 정할 수 있어요. 특정 요일에 고정하는 설정은 아니에요. 일주일보다 짧은 기간도 같은 사용 비율로 예상하고 마지막 요청 수량에서 올림해요.")
    )),
    GuideTopic("request-receive", "받은 물품 확인 · 분할 입고", "나누어 두 번 여러 번 배송 수령 체크 받은 양 남은 양 초과", listOf(
        GuideStep("저장한 요청에서 받은 물품을 체크해요", "입고 요청 계산기 → 저장한 요청 → 물품 받았어요를 누르세요. 실제 입고일을 확인하고 이번에 받은 품목만 체크해요. 체크하면 남은 요청량이 채워지므로 실제 받은 수량으로 고쳐 주세요. 체크하지 않은 품목은 이번 입고에 포함되지 않아요.", "52-request-receive"),
        GuideStep("받은 만큼만 재고에 더해요", "받은 수량 저장을 누르면 실제 재고와 받은 양에 함께 반영돼요. 요청 30EA 중 처음 15EA를 받았다면 남은 양은 15EA예요. 다음에 나머지를 받았을 때 같은 요청에서 다시 기록하면 돼요."),
        GuideStep("나머지와 이전 입고를 확인해요", "저장한 요청에서 요청·받은 양·남은 양을 확인하세요. 이전에 받은 내역에서 수량을 수정할 수 있어요. 재고 이력에서 입고 확인·취소를 누르면 잘못된 입고를 취소할 수 있어요. 수정·취소한 실제 입고에 맞춰 남은 양도 다시 계산해요.", "53-request-deliveries"),
        GuideStep("요청과 다르게 받아도 기록할 수 있어요", "요청보다 더 받은 양도 그대로 기록하며 초과분을 따로 보여줘요. 일부를 받은 뒤 요청량을 줄여도 실제 입고 내역은 사라지지 않아요. 한 번에 입력하는 입고 수량은 품목별 100,000EA까지예요.")
    )),
    GuideTopic("appointments", "병원 일정과 진료과", "예약 일정 시간 진료과 치료 검사 항목 다음 예약", listOf(
        GuideStep("진료과와 치료 항목을 준비해요", "설정 목록의 병원·연락처 구역에서 진료과와 검사·치료 항목을 바로 열어 이름·색상 또는 항목·아이콘을 등록해요. 치료 항목은 예약에서 여러 개를 함께 선택할 수 있어요."),
        GuideStep("예약 날짜와 시간을 입력해요", "홈의 병원 일정 등록 또는 +, 설정 → 병원 일정에서 예약을 추가하세요. 날짜를 고르고 진료과마다 예약시간을 입력해요. 시간은 09:30처럼 적거나 시간 선택을 이용해요. 치료 항목은 시간이 필요한 경우에만 항목별 시각을 지정하세요. 메모를 확인한 뒤 저장하세요.", "32-appointment-editor"),
        GuideStep("홈에서 일정 상세를 확인해요", "홈의 병원 일정 카드를 누르면 해당 예약의 날짜·진료과별 시간·치료 항목·메모와 예약일 기준 재고를 함께 볼 수 있어요. 일정 수정 또는 같은 구성으로 다음 예약을 눌러 이어서 작업하세요. 제목 옆 +는 새 예약을, 부족 경고 아이콘은 잔량 계산 상세를 바로 열어요.", "75-appointment-detail"),
        GuideStep("지금과 같은 사용 추세라면 남을 재고", "홈에서는 부족이 예상될 때만 다음 진료시간 옆에 경고 아이콘이 나타나요. 아이콘을 누르면 상세가 열려요. 설정 → 병원 일정의 예약일 기준 재고에서 부족 예상·잔량 있음·잔량 0·미확인을 빨강·초록·주황·회색 칩으로 확인해요. 품목별 예상 수량도 같은 색으로 표시하며 부족 품목을 먼저 보여줘요. 예상 잔량 계산 보기를 누르면 전체 품목의 계산을 볼 수 있어요. 최근 28일 중 확정 사용 기록이 있는 날의 평균으로 현재 재고에서 방문 전날까지의 사용량을 빼요. 추가 사용은 합산하고 기록 없는 날짜는 평균에서 제외해요. 오늘 이미 기록한 사용은 다시 빼지 않으며 방문일 사용 전 기준이에요. 재고 미등록·사용량 미확인·0·부족을 구분하고, 아직 받지 않은 요청은 더하지 않아요.", "73-stock-forecast-detail"),
        GuideStep("예상 사용을 직접 바꿔요", "예상 잔량 화면의 평소 사용 바꾸기에서 사용 구성·주간 비율·직접 사용량을 정하세요. 지정한 사용 구성대로라면으로 표시되고 병원 일정 전체에 적용돼요. 실제 재고와 저장한 요청은 바뀌지 않아요. 병원 일정 위젯은 일정 정보만 표시해요.", "72-stock-forecast"),
        GuideStep("다음 일정으로 재사용해요", "병원 일정 관리에서 예정·지난 일정을 확인하고 수정하거나 다음 예약에 재사용할 수 있어요. 재사용할 때 날짜와 시간은 새로 정해 주세요. 병원 일정을 저장해도 물품 사용량이나 재고가 바뀌지는 않아요.", "39-appointment-list")
    )),
    GuideTopic("contacts", "연락처와 전화 · 문자", "연락처 번호 이모지 아바타 전화 문자 연락 순서 정렬 위 아래 수정 삭제 더보기", listOf(
        GuideStep("자주 연락하는 곳을 등록해요", "설정 → 연락처에서 이름과 전화번호를 적고 이모지를 고르세요. 전화 연결과 문자 연결 허용을 각각 정한 뒤 저장해요. 번호에 공백이나 하이픈을 넣어도 입력할 수 있어요.", "34-contact-editor"),
        GuideStep("홈에서 연결 방법을 골라요", "홈의 연락처 아바타를 누르면 허용한 전화·문자 버튼이 보여요. 전화는 다이얼 화면, 문자는 작성 화면을 열어요. 실제 통화나 전송은 해당 앱에서 직접 실행하세요. 둘 다 꺼 두면 연결 버튼은 표시되지 않아요.", "35-contact-actions"),
        GuideStep("수정·삭제 메뉴를 열어요", "설정 → 연락처에서 연락처 오른쪽 ⋮를 누르세요. 수정으로 이름·번호·아바타·연결 허용을 바꿀 수 있어요. 삭제는 확인창에서 확인을 눌러야 적용되며, 홈에서도 사라져요. 메뉴 바깥을 누르면 닫혀요.", "62-contact-menu"),
        GuideStep("자주 쓰는 연락처를 앞으로 옮겨요", "연락처가 두 개 이상이면 설정 → 연락처 → 순서 변경을 누르세요. 위·아래 화살표로 옮긴 뒤 순서 저장을 누르면 관리 목록과 홈에 함께 적용돼요. 취소하면 기존 순서를 유지해요. 새 연락처는 마지막에 추가되며 저장한 순서도 백업·복원에 포함돼요.", "60-contact-order")
    )),
    GuideTopic("widgets", "홈 화면 위젯", "위젯 홈 추가 기록 어제 오늘 3단계 병원 일정 예약 갱신 새로고침 잠금 크기 배치 처치 4×1 4x1 4×2 2×2 한 칸 가로 세로", listOf(
        GuideStep("휴대폰 홈에 추가해요", "설정 → 홈 화면 위젯에서 기록 위젯 2×2 추가·4×2 추가 또는 일정 위젯 추가를 누르고 휴대폰의 추가 확인 창에서 배치하세요. 직접 추가하려면 휴대폰 홈의 빈 곳을 길게 누르고 위젯 → 페리로그를 찾으세요. 추가 메뉴와 크기는 홈 앱마다 다를 수 있어요.", "59-widget-settings"),
        GuideStep("어제와 오늘의 세 단계를 확인해요", "4×1·4×2는 어제·오늘을 좌우로, 2×2는 위아래로 표시해요. 높이가 넉넉하면 각 영역을 펼치고, 낮으면 간단한 행으로 바뀌어요. 활력 상태·사용 구성·투석 기록이 완료되면 파란 체크, 미완료면 빈 원으로 보여요. 기준은 앱 홈과 같고 개별 측정값이나 남은 입력 항목은 표시하지 않아요.", "63-widgets-light"),
        GuideStep("한 칸 높이로 줄여요", "기록 위젯을 길게 누르고 아래쪽 손잡이를 위로 올리면 4×1로 바뀌어요. 어제·오늘을 좌우에 놓고 각 날짜의 활력·구성·투석을 가로로 표시해요. 좁은 화면에서는 이름을 줄여 쓰며, 아이콘과 날짜별 기록 열기는 같아요. 홈 앱에 따라 크기 조절 방식이 다를 수 있어요.", "69-widgets-one-row-light"),
        GuideStep("긴 홈 화면에서는 펼쳐 보여요", "가로가 넓고 높으면 어제·오늘 카드 안에 세 단계를 세로로 펼쳐요. 폭이 좁고 높으면 날짜 카드 두 개를 위아래로 쌓아요. 완료 아이콘과 오늘의 강조 색은 그대로예요.", "67-widgets-launcher-light"),
        GuideStep("날짜를 눌러 이어 써요", "어제나 오늘 영역을 누르면 표시된 날짜의 기록이나 초안을 열어요. 추가투석만 미완료라면 세 단계는 유지하고 추가투석을 열어요. 제목은 앱 홈을 열며, 위젯을 누르는 것만으로 기록이나 물품 사용이 확정되지는 않아요. 작성 중인 숫자 형식에 오류가 있으면 먼저 입력 화면에서 고쳐 주세요."),
        GuideStep("병원 일정과 처치를 함께 봐요", "2×2에 가장 가까운 방문 하나의 D-day·날짜·진료과별 시간·처치를 표시해요. 길쭉하면 처치를 한 열로, 낮거나 항목이 많으면 두 열로 배치해 선택한 처치를 모두 보여요. 메모는 표시하지 않아요. 오늘은 D-day로 표시하고, 마지막 진료·치료 시간이 지나면 다음 방문으로 바뀌어요. 일정 영역은 해당 예약 수정, 제목은 전체 일정, 예약이 없다는 안내는 새 예약을 열어요.", "65-widgets-tall-light"),
        GuideStep("크기와 갱신·잠금을 확인해요", "같은 2×2라도 홈 앱의 격자와 화면 방향에 따라 모양이 달라요. 스크롤 없이 공간에 맞춰 배치·글씨·간격을 조절하며, 처치를 숨기거나 줄임표로 생략하지 않아요. 위젯 글씨는 휴대폰 글씨 배율보다 위젯 공간에 맞춰요. 작게 보이면 길게 눌러 위젯 크기를 늘려 주세요. 기록·예약 변경은 자동 반영되며 오른쪽 위 새로고침으로도 갱신해요. 절전 상태에서는 갱신이 늦어질 수 있어요. 앱 잠금과 관계없이 위젯 내용은 표시돼요. 눌러서 앱에 들어갈 때는 잠금을 해제해 주세요. 라이트·다크는 앱의 표시 설정을 따라요.", "68-widgets-launcher-dark")
    )),
    GuideTopic("settings", "설정 · 화면 · 알림 · 잠금·보호", "설정 목록 테마 다크 어둡게 글씨 알림 잠금 보호 캡처 스크린샷 녹화 공유 기준", listOf(
        GuideStep("설정 목록에서 바로 열어요", "홈 또는 재고의 톱니바퀴를 누르면 일반, 투석 기록·물품, 병원·연락처, 백업·데이터, 도움말·앱 정보 순으로 보여요. 각 구역의 항목이 한 목록에 펼쳐져 있어요. 스크롤해 원하는 항목을 누르면 바로 상세 화면이 열려요.", "18-settings"),
        GuideStep("일반 설정을 찾아요", "설정 목록 맨 위에서 화면·표시, 알림, 앱 잠금·화면 보호, 홈 화면 위젯을 바로 열어요. 메뉴 아래에는 현재 저장된 상태를 표시해요."),
        GuideStep("화면 테마를 바꿔요", "설정 → 화면·표시에서 시스템·밝게·어둡게를 정하고 화면 설정 저장을 누르세요. 글씨 크기는 휴대폰 설정을 따라요. 저장 전 나가면 변경 내용을 버릴지 확인해요.", "30-settings-toggles"),
        GuideStep("알림 시각을 정해요", "설정 → 알림에서 알림 시각을 저장하세요. 알림 허용·소리·진동은 시스템 알림 설정 열기에서 변경해요. Android 13 이상에서는 권한이 없으면 첫 실행에 OS 권한을 요청해요. Android 12는 시스템 알림 설정을 바로 사용해요. 이전 앱 내부 스위치 대신 OS 설정을 따르며, 절전 상태에서는 알림이 늦을 수 있어요.", "78-notification-settings"),
        GuideStep("저장 결과를 확인해요", "저장 결과는 상태 표시줄 아래에 잠시 내려왔다가 사라져요. 안내가 떠도 본문과 하단 저장 버튼은 움직이지 않아요. 기록 삭제 후 되돌리기도 상단 안내에서 눌러요.", "87-top-save-feedback"),
        GuideStep("잠금과 화면 보호를 각각 정해요", "설정 → 앱 잠금·화면 보호에서 각각 선택한 뒤 잠금·보호 설정 저장을 누르세요. 앱 잠금은 앱을 열거나 다른 앱에서 돌아올 때 인증해요. 먼저 휴대폰에 생체 인증이나 화면 잠금이 있어야 해요. 앱 잠금만 켜면 캡처·녹화는 허용돼요. 화면 보호는 캡처·녹화·화면 공유를 막고 최근 앱 미리보기를 가려요. 앱 잠금 없이도 사용할 수 있고, 캡처하려면 끄고 저장하세요. 처음 설치하면 둘 다 꺼져 있고, 기존 잠금 사용자는 두 옵션이 켜진 상태로 유지돼요. 위젯과 외부 백업 파일은 보호하지 않아요.", "81-settings-lock"),
        GuideStep("계산 기준을 저장해요", "설정 → 투석 계산 기준에서 이전 최종 주입 설정값과 적용일을 정하고 이 날짜부터 기준 저장을 누르세요. 새 기록에 적용하며 이미 저장한 기록의 기준은 유지해요.", "83-settings-basis")
    )),
    GuideTopic("backup", "백업 · 복원 · 기기 변경", "내보내기 가져오기 JSON 자동 폴더 보호 데이터 새 휴대폰", listOf(
        GuideStep("파일로 내보내요", "설정 → 데이터 내보내기·가져오기 → 전체 데이터 내보내기를 누르고 저장 위치를 고르세요. 기록·초안·재고·입고 요청과 연결된 입고·병원 일정·설정 등을 함께 보관해요. 백업 JSON 파일에는 암호가 없으므로 저장 위치를 확인해 주세요."),
        GuideStep("자동 백업 폴더를 연결해요", "설정 → 자동 백업 → 백업 폴더 선택을 누르세요. 매일 또는 매주와 보관 개수를 정한 뒤 백업 설정 저장을 누르세요. 지금 백업으로 바로 실행하고 최근 성공 시각을 확인할 수 있어요. 보관 개수 정리는 자동 백업 파일에만 적용돼요.", "19-backup"),
        GuideStep("복원은 전체 교체예요", "백업 파일 가져오기에서 파일을 고르고 표시된 내용을 확인한 뒤 복원하세요. 현재 자료와 합치지 않고 백업 내용으로 전체 교체해요. 복원 직전 현재 자료는 앱 내부 보호 백업으로 남겨요. 보호 파일은 설정 → 보호 백업에서 외부로 내보낼 수 있어요."),
        GuideStep("새 휴대폰으로 옮겨요", "기존 휴대폰에서 전체 데이터를 내보내고 파일을 새 휴대폰에 옮겨 가져오세요. 새 기기에서는 자동 백업 폴더를 다시 연결해 주세요. 앱을 삭제하면 내부 자료와 보호 백업도 지워지므로 먼저 외부 파일로 보관해 주세요.")
    )),
    GuideTopic("updates", "설치와 업데이트", "APK 다운로드 설치 버전 업데이트 앱 정보 실패 문의", listOf(
        GuideStep("앱 정보와 문의를 찾아요", "설정 → 앱 정보·문의에서 설치 버전·제작자를 확인하고 GitHub·릴리즈 · 변경 내역·버그 신고 · 기능 제안·이메일 문의를 열어요.", "25-about"),
        GuideStep("다운로드 후 설치해요", "설정 → 업데이트에서 업데이트 확인 후 새 버전이 있으면 버전 번호가 붙은 APK 다운로드를 누르세요. 파일 검증이 끝나면 같은 버전의 업데이트 설치를 눌러 Android 설치 화면으로 이동해요. 출처 허용이 필요하면 휴대폰 설정에서 허용한 뒤 돌아와 설치를 다시 누르세요.", "29-about-update"),
        GuideStep("실패하거나 취소한 경우", "설치가 취소되거나 막혀도 받은 APK는 Download 폴더에 남아요. 다운로드 폴더 열기에서 다시 열 수 있어요. 검증에 실패한 파일은 해당 버전의 다시 다운로드를 누르세요. 예전 APK만 있으면 최신 버전은 첫 다운로드로 표시해요. 이전 파일과 진행 중인 이전 다운로드는 자동 삭제·취소하지 않아요. 업데이트가 끝나도 APK를 자동으로 삭제하지 않아요."),
        GuideStep("기존 앱 위에 설치해요", "처음 설치할 때는 GitHub의 최신 릴리즈에서 APK를 내려받아 여세요. 업데이트할 때는 기존 앱을 삭제하지 않고 같은 서명의 새 APK를 위에 설치해요. 업데이트 전 전체 데이터를 내보내 두세요. 인터넷이 없어도 기록과 사용 안내는 열 수 있어요.")
    )),
    GuideTopic("faq", "자주 묻는 내용", "미완료 저장 안 됨 오프라인 빈칸 0 약 기록 누락 모름", listOf(
        GuideStep("저장 버튼이 눌리지 않아요", "필수 값과 숫자 입력 형식을 확인해 주세요. 입고 요청은 다음 방문일이 이번 방문일보다 뒤여야 해요. 빨간 안내가 있다면 해당 값을 고쳐 주세요. 물품 받았어요에서는 받은 품목을 체크하고 1EA 이상 입력해야 해요."),
        GuideStep("예상 수량이 실제와 달라요", "약이 붙은 값은 기록이나 직접 정한 사용 패턴으로 예상한 값이에요. 최근 사용 방식이 달라졌다면 평소 사용을 고치고, 방문일에 확인한 잔량이나 최종 요청 수량을 직접 입력하세요. 실제 받은 수량은 입고 화면에서 따로 확인해 주세요."),
        GuideStep("아직 기록이 없어요", "입고 요청 계산기 → 평소 사용 바꾸기에서 사용 구성 또는 품목별 직접 입력을 선택하세요. 재고를 모르면 보유량을 빼지 않은 필요량으로 시작할 수 있어요. 물품 자체가 없다면 품목 등록하기부터 진행해 주세요."),
        GuideStep("빈칸과 0은 같지 않아요", "치료 수치의 빈칸은 미입력이고 0은 실제 값이에요. 일반 입고에서 빈 수량·0EA는 제외해요. 요청 수량을 0으로 바꾸면 그 품목을 요청하지 않는 것으로 계산해요. 재고 미등록은 보유량이 0이라는 뜻이 아니에요."),
        GuideStep("안내를 봐도 모르겠어요", "각 화면의 ?를 누르면 관련 설명을 바로 볼 수 있어요. 전체 사용 안내에서 원하는 단어로 찾아보세요. 앱 동작 문제는 설정 → 앱 정보·문의 → 버그 신고 · 기능 제안 또는 이메일 문의로 전달할 수 있어요.")
    ))
)
